import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let S = {1,2,...,{n}} and define the reflection map φ(x) = {n}+1 - x. Fix {t}, a power of two. Let M be the number of bijections f: S → S such that for every a ∈ S, one has f^[{t}](a) + f^[-{t}](a) = {n}+1, where f^[k] denotes the k-fold iterate of f (and f^[-k] = (f^{-1})^[k]). Determine the largest integer k such that 2^k divides M.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose t as a power of two, at least 2, to make the instance strictly harder than the seed (which corresponds to t=1)
u = rng.randint(1, 6)  # t in {2,4,8,16,32,64}
t = 1 << u
# Choose r >= 2 so that there are multiple cycles of length 2t on the pair-quotient
r = rng.randint(2, 200)
# n must be 4 * r * t so that m = n/2 is divisible by 2t
n = 4 * r * t
return {"n": n, "t": t}

    def verifier(assign):
# Validate input
if not isinstance(assign, dict):
