if 'n' not in assign or 't' not in assign:
    return (False, None)
n = assign['n']
t = assign['t']
if not (isinstance(n, int) and isinstance(t, int)):
    return (False, None)
if n <= 0 or t <= 0:
    return (False, None)
# t must be a power of two, and n must be divisible by 4t
if t & (t - 1):
    # t is not a power of two
    return (False, None)
if n % (4*t) != 0:
    return (False, None)
# Compute k = v2(M), where M counts permutations f with f^{2t} = φ, equivalently f^[t](a) + f^[-t](a) = n+1 for all a.
# Let m = n/2 be number of φ-pairs; r = m/(2t) is the number of 2t-cycles on the pair-quotient.
m = n // 2
if m % (2*t) != 0:
    return (False, None)
r = m // (2*t)
if r <= 0:
    return (False, None)
# For t a power of two, all admissible roots correspond to:
# - a permutation g of the m pairs that is a product of r disjoint cycles, each of length 2t;
# - for each such cycle, 2^{2t-1} internal flip choices.
# Hence M = m! / ((2t)^r r!) * 2^{(2t-1)r}.
# We only need v2(M) = v2(m!) - r*v2(2t) - v2(r!) + (2t-1)r.

def v2_factorial(x):
    # Legendre's formula for 2-adic valuation: v2(x!) = x - s2(x), where s2 is the sum of binary digits.
    # Implement popcount without relying on int.bit_count for portability.
    def popcount(y):
        c = 0
        while y:
            y &= y - 1
            c += 1
        return c
    return x - popcount(x)

# v2(2t) = 1 + v2(t); for t a power of two, v2(t) = log2(t)
v2_2t = 1
tmp = t
while tmp % 2 == 0:
    v2_2t += 1
    tmp //= 2
# Subtract the extra increment: the loop counted starting from 1; fix to exact value
# Actually the loop above sets v2_2t = 1 + v2(t) + 1 due to initialization; correct it.
# Let's recompute cleanly:
v2_2t = 0
val = 2*t
while val % 2 == 0:
    v2_2t += 1
    val //= 2

k = v2_factorial(m) - r * v2_2t - v2_factorial(r) + (2*t - 1) * r
return True, k


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

